ck('Later investigator response rates agree',round(16/33*100,1)==48.5 and round(38/63*100,1)==60.3)
ck('Both published independent confidence intervals present',all(s in json.dumps(profile) for s in ['19.2-51.8','35.5-60.6']))
ck('No independent clinical approval implied',record['clinical_reviewed'] is False and record['clinical_use_authorised'] is False)
ck('No BRAF selection factor retained','BRAF' not in ' '.join(profile['treatment_rationale_factors_replace']))
ck('Source cohort and assessor distinctions retained',all(s in record['primary_endpoint'] for s in ['RECIST 1.0','Locally advanced','biopsy']))
